  ) AS v(id, title, subject, grade_level, chapter, lesson_id)
  JOIN public.lessons l ON l.id = v.lesson_id
 WHERE NOT EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.lesson_id = l.id)
ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('c8418a3d-f65a-58ed-b2be-0ce0159c057c'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'Que désigne l’ethos dans la rhétorique aristotélicienne ?', 'mcq', '["L’image que l’orateur donne de lui-même","L’argument rationnel","L’émotion du public","Le style du discours"]'::jsonb, 0, 'Logos, ethos, pathos forment les trois leviers.', 1),
    ('eb7f02c3-cf0a-5c55-9d37-61d7f2c6c531'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'Convaincre s’adresse à la raison, persuader à la sensibilité.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La distinction est classique depuis la rhétorique antique.', 2),
    ('c9e7e4e1-d3ea-55f0-bce6-1bc5d88af575'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'Dans le *Gorgias*, Platon compare la rhétorique à…', 'mcq', '["La cuisine, qui flatte au lieu de soigner","La médecine","La géométrie","La musique"]'::jsonb, 0, 'Elle procure du plaisir sans procurer le bien.', 3),
    ('6ae210d1-a487-57aa-a60c-0d0cb05e086b'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'Le sophiste, selon Platon, cherche avant tout…', 'mcq', '["À avoir raison","À dire le vrai","À se taire","À enseigner la géométrie"]'::jsonb, 0, 'D’où l’opposition avec le philosophe.', 4),
    ('ea193bc6-4701-5d5f-842d-2cff53ae4a25'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'L’anaphore consiste à répéter un mot en début de phrases successives.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une figure d’insistance très utilisée en éloquence politique.', 5),
    ('b8b7b9a2-180e-5d99-a43b-1506bfe0930e'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'Le pathos désigne…', 'mcq', '["L’émotion suscitée chez l’auditoire","La logique du raisonnement","L’autorité de l’orateur","Le lieu du discours"]'::jsonb, 0, 'Il peut servir la vérité comme la manipulation.', 6),
    ('6870efdf-482a-5fc4-be17-88d8ce072460'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'Une parole efficace est nécessairement une parole vraie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est précisément le problème que pose la rhétorique.', 7),
    ('e9950b55-dfbd-5494-bf38-a5cde9633c20'::uuid, 'bb4ecdca-5e50-5d6f-827f-8948af6dab53'::uuid, 'Selon Pascal, l’homme est mené uniquement par la raison.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il insiste au contraire sur le rôle de l’imagination et de la coutume.', 8),
    ('0d225ffd-23f4-5b5f-a771-ffe44ac862e3'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, 'Qui écrit « chacun appelle barbarie ce qui n’est pas de son usage » ?', 'mcq', '["Montaigne","Montesquieu","Voltaire","Rousseau"]'::jsonb, 0, 'Dans le chapitre « Des cannibales » des *Essais*.', 1),
    ('60a1b7a3-9296-5126-a2ce-33fd8d3f7af4'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, 'Qui a inventé le mot « utopie » ?', 'mcq', '["Thomas More","Platon","Rabelais","Orwell"]'::jsonb, 0, 'En 1516, à partir du grec : le lieu de nulle part.', 2),
    ('04a0869b-a117-5bff-b4c1-32e2befcb4c4'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, 'Une dystopie décrit une société idéale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le contraire : une société cauchemardesque, souvent née d’une utopie.', 3),
    ('c5b5b4d8-0f60-54d1-9787-888a99e3e956'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, 'Dans les *Lettres persanes*, Montesquieu utilise…', 'mcq', '["Le regard étranger pour critiquer la société française","Un récit de voyage authentique","Un traité scientifique","Une tragédie"]'::jsonb, 0, 'Le détour rend visible ce qui passait pour naturel.', 4),
    ('5fe5359d-d72f-516b-81e8-d5406e1cd0e6'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, 'Descartes veut rendre l’homme « comme maître et possesseur de la nature ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Formule du *Discours de la méthode* (1637).', 5),
    ('d030eb03-6c84-5169-ab83-92d52b1d8daa'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, 'Le relativisme culturel consiste à…', 'mcq', '["Juger une culture selon ses propres critères","Classer les cultures","Refuser toute culture","Imposer une culture"]'::jsonb, 0, 'Il naît du choc des grandes découvertes.', 6),
    ('20c5b21f-f749-5bb0-be90-83a1c9924f02'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, 'La révolution scientifique fait de la nature un ensemble de lois mesurables.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle cesse d’être un texte symbolique à déchiffrer.', 7),
    ('7aa6ca4d-e671-5fe1-85f5-49fcd2cce413'::uuid, 'bc2f4fc8-769a-5d84-98f5-0d86628eec5b'::uuid, '*1984* d’Orwell relève…', 'mcq', '["De la dystopie","De l’utopie","De l’essai","De l’autobiographie"]'::jsonb, 0, 'Publié en 1949, il décrit un totalitarisme achevé.', 8),
    ('b27a5b41-046e-55c5-9624-981fe8f1af71'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'L’interprétation littéraire part…', 'mcq', '["Du texte lui-même","D’une question générale","D’une opinion personnelle","D’une biographie"]'::jsonb, 0, 'C’est l’exercice ancré dans les procédés du texte.', 1),
    ('c8fb71ab-4564-518f-865c-0410d40d2076'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'Un essai philosophique est une opinion personnelle argumentée librement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un raisonnement problématisé, qui affronte les objections.', 2),
    ('d198083c-5f73-548c-9333-d9446c77681b'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'Problématiser consiste à…', 'mcq', '["Montrer pourquoi la réponse évidente ne suffit pas","Poser un thème","Résumer le cours","Donner un exemple"]'::jsonb, 0, 'Sans tension, il n’y a pas de problème philosophique.', 3),
    ('e8ff8bee-6e6d-5fe2-a209-ddf567742ee5'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'Une interprétation littéraire doit montrer comment la forme produit le sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sinon, elle se réduit à une paraphrase.', 4),
    ('64328ef8-aa75-5e64-81ef-76915f4a80bd'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'Que doit accompagner l’affirmation « l’auteur critique la société » ?', 'mcq', '["Un élément précis du texte qui le montre","Une citation d’un autre auteur","Une date","Un résumé de l’œuvre"]'::jsonb, 0, 'Sans preuve textuelle, l’affirmation reste creuse.', 5),
    ('3b849681-52d7-5ae0-b68a-391c98154469'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'Un bon plan juxtapose des parties indépendantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doit progresser : la dernière partie dépend des précédentes.', 6),
    ('b5848c20-eb20-51f4-bae6-8f0744e73304'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'Paraphraser un texte, c’est…', 'mcq', '["Le redire autrement sans l’expliquer","L’analyser","Le critiquer","Le citer"]'::jsonb, 0, 'C’est le défaut le plus fréquent en interprétation.', 7),
    ('546ad0c2-3e34-58a3-94ff-5a53b519fb13'::uuid, 'a386705a-2c94-53ad-b36f-ce69d049945d'::uuid, 'Formuler une question vaut mieux que poser un thème.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une question oriente le raisonnement ; un thème ne dit rien.', 8),
    ('b5dca92c-0a53-53bb-ae89-43b6f3cd953a'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, 'Qui écrit *Émile ou De l’éducation* ?', 'mcq', '["Rousseau","Montaigne","Voltaire","Diderot"]'::jsonb, 0, 'Publié en 1762.', 1),
    ('76dd1acd-8003-5133-9c9e-2b641f5599c7'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, 'Selon Freud, le moi n’est pas « maître dans sa propre maison ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’inconscient agit sans que la conscience le sache.', 2),
    ('3b26e301-3b00-5904-86b2-b6a500e96db9'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, '« Connais-toi toi-même » est une maxime…', 'mcq', '["Inscrite au temple de Delphes et reprise par Socrate","De Descartes","De Freud","De Rousseau"]'::jsonb, 0, 'Elle ouvre la tradition de l’examen de soi.', 3),
    ('59e4abb1-3384-5fa7-8947-f452dfacdb46'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, 'L’autobiographie restitue fidèlement le moi tel qu’il est.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le récit sélectionne et ordonne : il construit autant qu’il restitue.', 4),
    ('20b368e2-5cb7-51d0-a352-5b17152b416d'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, 'Qui a inauguré l’écriture de soi avec les *Confessions* au IVe siècle ?', 'mcq', '["Saint Augustin","Rousseau","Montaigne","Pascal"]'::jsonb, 0, 'Rousseau reprendra le titre au XVIIIe siècle.', 5),
    ('ceb1b75a-155d-55f1-8fd8-aec6b799eb22'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, 'Selon Hegel, la conscience de soi passe par la reconnaissance d’autrui.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La dialectique du maître et de l’esclave en est l’expression.', 6),
    ('b6b44fa4-64d8-5f10-bffb-85bb8236f1fb'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, 'Pour Sartre, le regard d’autrui…', 'mcq', '["Me fige en objet","Me libère toujours","M’est indifférent","Me révèle ma nature"]'::jsonb, 0, 'D’où la formule « l’enfer, c’est les autres ».', 7),
    ('a32074a4-b5dd-57e2-9c04-c83dbcffbb12'::uuid, '5af6bbcd-e238-54cd-8f2e-b03ede370a05'::uuid, 'Le roman d’apprentissage met en scène la formation d’un personnage.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le héros se construit en se heurtant au monde.', 8),
    ('36a3c024-721d-5159-a95e-4d3a2e572f30'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'Quel critère Lévi-Strauss propose-t-il pour distinguer nature et culture ?', 'mcq', '["L’universel relève de la nature, le variable de la culture","L’ancien contre le moderne","Le corps contre l’esprit","L’individu contre le groupe"]'::jsonb, 0, 'La prohibition de l’inceste met ce critère en difficulté.', 1),
    ('380d764e-25bf-5fd1-bb9b-d14e0811d8bf'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'Hannah Arendt a analysé la « banalité du mal ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À propos du procès Eichmann, en 1961.', 2),
    ('2f5745e6-a9eb-5996-9159-3d969b01ddc8'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'Qui formule le « principe responsabilité » face à la technique ?', 'mcq', '["Hans Jonas","Karl Marx","Michel Foucault","Jean-Paul Sartre"]'::jsonb, 0, 'Il l’oriente vers les générations futures.', 3),
    ('72349df5-04e1-5f82-8a9f-472c6733a9f4'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'La culture garantit contre la barbarie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le XXe siècle a montré le contraire, ce qui met l’humanisme en procès.', 4),
    ('72beb04a-558b-5ea1-8675-b502e5c88147'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'Le transhumanisme interroge…', 'mcq', '["La possibilité d’augmenter techniquement l’humain","Le retour à la nature","La fin des sciences","L’origine des espèces"]'::jsonb, 0, 'Génétique, prothèses, IA : la finitude devient un problème technique.', 5),
    ('7af0642e-0262-5030-a597-6c54172a233d'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'Primo Levi a témoigné de l’expérience concentrationnaire.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Notamment dans *Si c’est un homme*.', 6),
    ('a7b1b777-ed57-5765-957f-3514775e1fb5'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'La prohibition de l’inceste est intéressante parce qu’elle est…', 'mcq', '["À la fois universelle et culturellement réglée","Purement biologique","Récente","Propre à l’Occident"]'::jsonb, 0, 'Elle se tient exactement à la charnière nature/culture.', 7),
    ('096825cf-8b80-5443-9056-8e65e5a382dd'::uuid, '0ec57f3b-039d-5357-9a56-d9385ce291f7'::uuid, 'L’humanisme place l’homme au centre de la réflexion.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce geste que le XXe siècle interroge.', 8),
    ('08865e91-e623-564a-8195-e9f7318ebfa5'::uuid, '800fbdb5-1d05-5fdc-bfc9-b512b9a87aef'::uuid, 'Combien de temps dure l’épreuve de HLP en terminale ?', 'mcq', '["4 heures","2 heures","3 heures","5 heures"]'::jsonb, 0, 'Deux exercices notés sur 10 chacun.', 1),
    ('c23214c3-e885-5d03-ae75-c1fd83f654c8'::uuid, '800fbdb5-1d05-5fdc-bfc9-b512b9a87aef'::uuid, 'Les deux exercices portent sur un même texte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’essai élargit la question soulevée par le texte.', 2),
    ('512a0b14-c8bb-5c00-92dd-4d1e34e50367'::uuid, '800fbdb5-1d05-5fdc-bfc9-b512b9a87aef'::uuid, 'Quelle est l’erreur la plus fréquente en interprétation littéraire ?', 'mcq', '["La paraphrase","L’excès de citations","Le plan en trois parties","L’introduction trop courte"]'::jsonb, 0, 'Redire le texte n’est pas l’analyser.', 3),
    ('cc201949-a725-58e5-b0ce-2391ba09b8be'::uuid, '800fbdb5-1d05-5fdc-bfc9-b512b9a87aef'::uuid, 'Réciter le cours sans répondre à la question est valorisé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le hors-sujet le plus courant, et le plus sanctionné.', 4),
    ('83455b63-4f16-5dcb-8683-ac8239c95172'::uuid, '800fbdb5-1d05-5fdc-bfc9-b512b9a87aef'::uuid, 'Un exemple personnel est acceptable dans l’essai…', 'mcq', '["S’il est précis et sert l’argument","Jamais","Toujours","Seulement en conclusion"]'::jsonb, 0, 'C’est sa précision qui le rend recevable.', 5),
    ('e8601cc9-898e-5c23-b683-07eb182c8101'::uuid, '800fbdb5-1d05-5fdc-bfc9-b512b9a87aef'::uuid, 'Combien de temps consacrer environ à chaque exercice ?', 'mcq', '["2 heures","1 heure","3 heures","30 minutes"]'::jsonb, 0, 'Dont une vingtaine de minutes de préparation.', 6),
