    ('5f0fcfde-5a91-5f04-95d6-b5a6fa86166c'::uuid, '6a4a2f81-252d-5c58-9be7-b16d42762b9b'::uuid, 'Un réducteur réalise la fonction « transmettre ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il adapte vitesse et couple entre le moteur et l’effecteur.', 6),
