    ('b44d9996-aaaf-5b15-8704-2ee334d803ef'::uuid, '7a1385d4-ad46-505b-8590-a54bb2b545ef'::uuid, 'Le rendement d’un système réel peut dépasser 1.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il y a toujours des pertes : chaleur, frottement, bruit.', 2),
    ('e29a2651-b0e4-5a32-ae01-dfa40a8a9aa1'::uuid, '7a1385d4-ad46-505b-8590-a54bb2b545ef'::uuid, 'Trois éléments de rendement 0,9 en cascade donnent un rendement global de…', 'mcq', '["0,73 environ","0,9","2,7","0,3"]'::jsonb, 0, 'Les rendements se multiplient : 0,9³ ≈ 0,729.', 3),
    ('673f3c02-7075-55f9-8bb9-c8c17e6ef748'::uuid, '7a1385d4-ad46-505b-8590-a54bb2b545ef'::uuid, 'En électricité, la puissance vaut…', 'mcq', '["U × I","U / I","U + I","U² × I"]'::jsonb, 0, 'En courant continu, P = U × I.', 4),
    ('3a386ce5-a281-51f1-9f75-4adea8936e54'::uuid, '7a1385d4-ad46-505b-8590-a54bb2b545ef'::uuid, 'Un réducteur augmente le couple en diminuant la vitesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le produit couple × vitesse se conserve, aux pertes près.', 5),
