    ('7bbb686d-f2b6-5811-88da-18d3a895f0e5'::uuid, '2c9faf8f-1621-5f7b-8cf7-99c4a9159cee'::uuid, 'Combien de niveaux offre une conversion sur 10 bits ?', 'mcq', '["1024","100","512","2048"]'::jsonb, 0, '2 puissance 10.', 2),
