    ('1e2140fb-e6dd-5b9d-89bf-c148bfacb926'::uuid, '2c9faf8f-1621-5f7b-8cf7-99c4a9159cee'::uuid, 'Quel outil décrit le mieux un système séquentiel ?', 'mcq', '["Le diagramme d’états","Le schéma cinématique","Le diagramme des exigences","La nomenclature"]'::jsonb, 0, 'États, transitions, conditions de franchissement.', 6),
