    ('989e3d68-644d-5315-8235-28e04b862372'::uuid, '2c9faf8f-1621-5f7b-8cf7-99c4a9159cee'::uuid, 'Un capteur de température analogique délivre…', 'mcq', '["Un signal continu proportionnel à la grandeur","Un signal binaire","Une trame I2C","Une impulsion unique"]'::jsonb, 0, 'Il doit ensuite être numérisé par un CAN.', 8),
    ('3c4578e9-7d77-52d8-855d-fa294a7fa81e'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'Que calcule le comparateur d’un système asservi ?', 'mcq', '["L’erreur entre la consigne et la mesure","La puissance consommée","Le rendement","La vitesse maximale"]'::jsonb, 0, 'C’est cette erreur que le correcteur traite.', 1),
    ('a500e21e-0cac-567a-82e1-268a2dfa7513'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'Quelles sont les trois performances d’un asservissement ?', 'mcq', '["Stabilité, précision, rapidité","Puissance, couple, vitesse","Coût, poids, taille","Fiabilité, sécurité, confort"]'::jsonb, 0, 'Elles sont largement antagonistes.', 2),
    ('efdbf749-286a-5170-98e6-df356ac61110'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'L’action intégrale permet d’annuler l’erreur statique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle accumule l’erreur jusqu’à la faire disparaître, au prix de la rapidité.', 3),
    ('d109a5f4-4cc3-52d0-8076-1c7f8d3f19e0'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'Quelle action du PID amortit les oscillations mais amplifie le bruit ?', 'mcq', '["L’action dérivée","L’action proportionnelle","L’action intégrale","Aucune"]'::jsonb, 0, 'Elle réagit à la vitesse de variation de l’erreur.', 4),
    ('d1abce7c-a00a-59b1-86f2-52ba8f10b7dc'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'En boucle ouverte, une perturbation est automatiquement corrigée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sans mesure de la sortie, le système ne sait pas qu’il dévie.', 5),
    ('374e399a-5789-5f25-ae99-e80dd5f85e50'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'Le dépassement se lit sur…', 'mcq', '["La réponse indicielle","Le diagramme d’états","La nomenclature","Le schéma électrique"]'::jsonb, 0, 'Avec le temps de réponse à 5 % et l’erreur statique.', 6),
    ('0e50e198-8e0e-5cc3-bd0d-384f12675c9e'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'Augmenter le gain proportionnel améliore toujours le système.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il accélère mais peut rendre le système oscillant, voire instable.', 7),
    ('88a3bdbf-3f7d-530a-8557-11492b199ba6'::uuid, '01e50e16-1a61-5abf-b4ec-9b5396c52354'::uuid, 'Un correcteur agit à partir de…', 'mcq', '["L’erreur","La consigne seule","La mesure seule","La puissance disponible"]'::jsonb, 0, 'C’est la différence consigne − mesure qui pilote la correction.', 8),
    ('3509a7b6-3280-5d37-8aa9-256f164eeec0'::uuid, '9091ff57-0f6d-5ede-a101-e9c90c70b05b'::uuid, 'Un modèle est…', 'mcq', '["Une représentation simplifiée valide dans un domaine donné","Une copie exacte du réel","Un prototype","Un plan de fabrication"]'::jsonb, 0, 'Il répond à une question précise, pas à toutes.', 1),
    ('40bf2907-308e-5e26-b09a-c273067e8906'::uuid, '9091ff57-0f6d-5ede-a101-e9c90c70b05b'::uuid, 'Un écart entre simulation et mesure invalide forcément le modèle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut d’abord examiner les hypothèses simplificatrices retenues.', 2),
    ('af4e2019-58fb-5162-9ef3-11b3ff0007fe'::uuid, '9091ff57-0f6d-5ede-a101-e9c90c70b05b'::uuid, 'Quel diagramme SysML décrit ce que le système doit faire ?', 'mcq', '["Le diagramme des exigences","Le diagramme de blocs internes","Le diagramme d’états","Le diagramme de séquence"]'::jsonb, 0, 'Il traduit le cahier des charges.', 3),
    ('4131bf33-5978-5fca-b048-82445000fdc8'::uuid, '9091ff57-0f6d-5ede-a101-e9c90c70b05b'::uuid, 'Une simulation multiphysique couple plusieurs domaines.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Mécanique, électrique, thermique, informatique.', 4),
    ('c0b713e0-600b-584d-92fd-4954bcb5bfac'::uuid, '9091ff57-0f6d-5ede-a101-e9c90c70b05b'::uuid, 'Le diagramme de blocs internes décrit…', 'mcq', '["Les échanges entre les composants","La liste des exigences","Le comportement temporel","Le coût"]'::jsonb, 0, 'Flux d’énergie, de matière et d’information.', 5),
