    ('4b36ff8a-bec9-5c8b-9cf8-32d561a0e5ae'::uuid, 'b2bc971d-9338-52d2-bd5d-80cd24017cb6'::uuid, 'Le GPS émet des signaux vers les satellites pour se localiser.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le récepteur ne fait qu’écouter : il n’émet rien.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('hlp', 'llcer-anglais', 'maths-complementaires', 'si', 'snt');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('hlp', 'llcer-anglais', 'maths-complementaires', 'si', 'snt')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 219 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 219 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
